(window.LMP_I18N = window.LMP_I18N || {})["hi"] = {"cap.think":"सोच रहा हूँ","cap.think.body":"जवाब देने से पहले कदम-दर-कदम सोचता है। गणित, तर्क और योजना में बेहतर — और आप उसके विचार पढ़ सकते हैं।","cap.tools":"टूल","cap.tools.body":"जवाब के बीच में JavaScript चला सकता है, वेब पर खोज सकता है या कोई पेज पढ़ सकता है — सिर्फ़ तब, जब आप टूल चालू करें।","cap.vision":"विज़न","cap.vision.body":"फ़ोटो समझता है। एक छोटा इमेज ऐड-ऑन मॉडल के साथ अपने-आप डाउनलोड हो जाता है।","card.branch":"<b>मन बदल गया? कोई बात नहीं।</b> संदेश संपादित करें, जवाब फिर से बनाएँ, या शुरू से शुरू किए बिना नई चैट में शाखा बनाएँ।","card.branch.a1":"मेपल के पत्ते झरे…","card.branch.a2":"ताल पर ठंडी बारिश…","card.branch.q":"शरद ऋतु पर एक हाइकु लिखो।","card.branch.tag":"↳ नई चैट में शाखा बनाई गई","card.docs":"<b>अपनी फ़ाइलों से पूछें।</b> PDF, Word, EPUB या Markdown — अर्थ के आधार पर खोज, और सही अंशों से जवाब।","card.docs.a":"शुरुआती छह महीनों के बाद, <b>60 दिन के लिखित नोटिस</b> के साथ। <span class=\"muted\">— धारा 8</span>","card.docs.indexed":"इंडेक्स हो गया","card.docs.q":"मैं अपनी लीज़ कब खत्म कर सकता हूँ?","card.prompts":"<b>भूमिका एक बार तय करें।</b> सिस्टम प्रॉम्प्ट सेव करें — कोई पर्सोना, लहजा या फ़ॉर्मेट — और किसी भी मॉडल के साथ दोबारा इस्तेमाल करें।","card.prompts.p1":"संक्षिप्त · फ़्रेंच में जवाब","card.prompts.p2":"सीनियर Kotlin रिव्यूअर","card.prompts.p3":"ऐसे समझाओ जैसे मैं पाँच साल का हूँ","card.tools":"<b>उसे काम करने दें।</b> सक्षम मॉडल जवाब के बीच में JavaScript चला सकते हैं, वेब पर खोज सकते हैं या कोई पेज पढ़ सकते हैं।","card.tools.off":"डिफ़ॉल्ट रूप से बंद","card.tools.results":"5 नतीजे","card.vision":"<b>उसे एक फ़ोटो दिखाएँ।</b> फ़ोटो लें या कोई इमेज चुनें और उसके बारे में पूछें — टेक्स्ट पढ़वाएँ, दृश्य का वर्णन पाएँ, चीज़ें पहचानें।","card.vision.a":"धूप वाले दिन हरे चरागाह में चरती एक रोएँदार भेड़।","card.vision.alt":"खेत में चरती एक भेड़","card.voice":"<b>टाइप करने के बजाय बोलें।</b> आप बोलते जाते हैं और शब्द दिखते जाते हैं, 35 भाषाओं में। पहचान पूरी तरह ऑफ़लाइन होती है।","card.voice.q":"लिस्बन की तीन दिन की यात्रा प्लान करो, अच्छी कॉफ़ी के साथ और…","control.body1":"<b>स्लाइडर खिसकाएँ और जवाब बदलते देखें।</b> तापमान तय करता है कि मॉडल कितना साहसी होगा — तथ्यों और कोड के लिए कम, ब्रेनस्टॉर्मिंग के लिए ज़्यादा।","control.body2":"Top‑P, Top‑K, Min‑P, दोहराव पेनल्टी, सीड और संदर्भ आकार भी मौजूद हैं, और हर मॉडल अपनी सेटिंग्स ख़ुद याद रखता है।","control.eyebrow":"नियंत्रण","control.title":"व्यक्तित्व, आपके हिसाब से।","cta.body":"इंस्टॉल होने में सेकंड। मॉडल डाउनलोड में मिनट। उसके बाद क्लाउड को अलविदा।","cta.source":"GitHub पर सोर्स कोड देखें","cta.title":"कोई भी मॉडल।<br/>आपकी जेब में।","faq.a1":"LM Playground आपको सीधे अपने Android डिवाइस, iPhone या iPad पर बड़े भाषा मॉडल चलाने देता है। सभी प्रोसेसिंग स्थानीय रूप से होती है – क्लाउड सर्वर की आवश्यकता नहीं है।","faq.a10":"**iPhone & iPad:** सेटिंग्स में जाएँ, फिर मॉडल में। डाउनलोड किए गए मॉडल पर बाईं ओर स्वाइप करें और डिलीट करें पर टैप करें।\n**Android:** सेटिंग्स में जाएं, फिर मॉडल में। “डाउनलोड किए गए” सेक्शन में, जिस मॉडल को हटाना चाहते हैं उसके पास डिलीट आइकन पर टैप करें।","faq.a11":"सिस्टम प्रॉम्प्ट एक पुनः उपयोग योग्य निर्देश है जो तय करता है कि मॉडल कैसे जवाब देता है — उदाहरण के लिए, “आप एक संक्षिप्त विज्ञान शिक्षक हैं। रोज़मर्रा के उदाहरणों के साथ विचारों को स्पष्ट रूप से समझाएँ।” या “आप एक वरिष्ठ कोड समीक्षक हैं। बग, एज केस और सुरक्षा समस्याओं की ओर इशारा करें।” इन्हें सेटिंग्स → सिस्टम प्रॉम्प्ट में बनाएँ और प्रबंधित करें, फिर किसी एक को अपनी चैट पर लागू करें। ये आपके डिवाइस पर संग्रहीत होते हैं और केवल स्थानीय मॉडल को भेजे जाते हैं।","faq.a12":"टूल सक्षम मॉडलों को जवाब के दौरान कार्रवाई करने देते हैं। तीन उपलब्ध हैं: JavaScript चलाएँ (ऑन-डिवाइस सैंडबॉक्स में गणित, तारीखें और टेक्स्ट प्रोसेसिंग), वेब खोज (वेब पर मौजूदा जानकारी ढूँढता है), और वेब पेज फ़ेच करें (किसी पेज को पढ़ता है ताकि मॉडल उसका सारांश दे सके या उद्धृत कर सके)। इन्हें सेटिंग्स → टूल में चालू करें। हर एक डिफ़ॉल्ट रूप से बंद है और केवल उन मॉडलों के साथ काम करता है जो टूल कॉलिंग का समर्थन करते हैं — मॉडल सिलेक्टर में हैमर बैज देखें।","faq.a13":"केवल जब आप उन्हें चालू करते हैं। वेब खोज मॉडल की क्वेरी DuckDuckGo को भेजती है, और वेब पेज फ़ेच करें उन पेजों को डाउनलोड करता है जिन्हें मॉडल खोलने का चयन करता है — वे अनुरोध स्वयं वेबसाइटों को जाते हैं, डेवलपर को नहीं। JavaScript चलाएँ पूरी तरह आपके डिवाइस पर बिना इंटरनेट एक्सेस के रहता है। हर टूल बंद होने पर (डिफ़ॉल्ट), कुछ भी आपके डिवाइस से बाहर नहीं जाता। विवरण के लिए गोपनीयता नीति देखें।","faq.a14":"**iPhone & iPad:** नहीं। iOS ऐप्स को बैकग्राउंड में GPU इस्तेमाल नहीं करने देता, इसलिए दूसरे ऐप पर जाते ही जवाब रुक जाता है। अब तक लिखा गया हिस्सा रहता है, और वापस आने पर जारी रखें बटन उसे पूरा कर देता है।\n**Android:** हाँ। जब ऐप बैकग्राउंड में होता है, तो एक सूचना मॉडल की स्थिति को ट्रैक करती है — लोड हुआ, जनरेट हो रहा है, फिर प्रतिक्रिया तैयार — और आपको जवाब कॉपी या साझा करने देती है। आप सेटिंग्स → ध्वनि और हैप्टिक में एक छोटी समाप्ति ध्वनि भी सक्षम कर सकते हैं। मॉडल डाउनलोड अपनी प्रगति सूचना गति और ETA के साथ दिखाते हैं।","faq.a15":"नहीं। चैट इनपुट में माइक्रोफ़ोन पर टैप करें और बोलें — एक स्पीच-रिकग्निशन मॉडल आपके बोलते ही आपके शब्दों को आपके फ़ोन पर टेक्स्ट में बदल देता है, 35 भाषाओं में। ऑडियो न कभी सेव होता है, न कहीं भेजा जाता है, इसलिए डिक्टेशन पूरी तरह ऑफ़लाइन काम करता है। मॉडल (718 MB) एक बार डाउनलोड होता है, जब आप पहली बार माइक्रोफ़ोन इस्तेमाल करते हैं।","faq.a2":"ऐप Q4_K_M क्वांटाइज़ेशन के साथ GGUF फॉर्मेट के मॉडल को सपोर्ट करता है, जिसमें विभिन्न आकारों में Qwen 3, Gemma 3, Llama 3.2, Phi‑4 mini और DeepSeek R1 Distill शामिल हैं।","faq.a3":"मॉडल का आकार लगभग 500 MB (छोटे मॉडल जैसे Qwen 3 0.6B) से लेकर कई GB (बड़े मॉडल जैसे DeepSeek R1 7B) तक होता है। डाउनलोड करने से पहले सुनिश्चित करें कि आपके पास पर्याप्त जगह है।","faq.a4":"इंटरनेट मॉडल डाउनलोड करने के लिए, और — यदि आप उन्हें चालू करते हैं — वैकल्पिक वेब टूल (वेब खोज और पेज फ़ेच) के लिए ज़रूरी है। इसके अलावा, मॉडल डाउनलोड होने के बाद आपके डिवाइस पर पूरी तरह ऑफ़लाइन चलता है।","faq.a5":"आपकी बातचीत आपके डिवाइस पर स्थानीय रूप से प्रोसेस होती है और ऐप द्वारा कभी किसी सर्वर को नहीं भेजी जाती। एकमात्र अपवाद वैकल्पिक वेब टूल हैं: यदि आप वेब खोज या पेज फ़ेच चालू करते हैं, तो मॉडल की खोज क्वेरी और जो पेज वह खोलता है, वे उन वेबसाइटों को भेजे जाते हैं (खोज DuckDuckGo का उपयोग करती है)। टूल डिफ़ॉल्ट रूप से बंद हैं, इसलिए जब तक आप उन्हें चालू नहीं करते तब तक कुछ भी आपके डिवाइस से बाहर नहीं जाता। विवरण के लिए गोपनीयता नीति देखें।","faq.a6":"बड़े मॉडल को मेमोरी में लोड होने में अधिक समय लगता है। लोडिंग समय आपके डिवाइस के हार्डवेयर पर निर्भर करता है। लोड होने के बाद, मॉडल आपके अनलोड करने तक मेमोरी में रहता है।","faq.a7":"अधिक RAM वाले डिवाइस बड़े मॉडल चला सकते हैं। सर्वोत्तम प्रदर्शन के लिए, छोटे मॉडल के लिए कम से कम 6 GB RAM और बड़े मॉडल के लिए 8+ GB RAM वाला डिवाइस उपयोग करें।","faq.a8":"**iPhone & iPad:** हाँ। सेटिंग्स → मॉडल में इंपोर्ट करें पर टैप करें और .gguf फ़ाइल चुनें, या Files ऐप में उसे LM Playground के Models फ़ोल्डर में कॉपी करें। ऐप उसे अपने-आप पहचान लेता है और बिल्ट-इन कैटलॉग के साथ दिखाता है। चैट टेम्पलेट और टोकनाइज़र सेटिंग्स GGUF मेटाडेटा से पढ़ी जाती हैं। अगर कोई खास मॉडल काम न करे, तो कृपया GitHub पर issue खोलें।\n**Android:** हाँ। अपनी .gguf फ़ाइल को सेटिंग्स → मॉडल में चुने गए स्टोरेज फ़ोल्डर (वही फ़ोल्डर जो डाउनलोड के लिए उपयोग होता है) में रखें। ऐप इसे अपने आप पहचान लेगा और इसे अंतर्निर्मित कैटलॉग के साथ मॉडल चयनकर्ता में दिखाएगा। चैट टेम्पलेट और टोकनाइज़र सेटिंग्स GGUF मेटाडेटा से पढ़ी जाती हैं। यदि कोई विशिष्ट मॉडल काम नहीं करता, तो कृपया GitHub पर इश्यू खोलें।","faq.a9":"**iPhone & iPad:** LM Playground के Models फ़ोल्डर में, जिसे आप Files ऐप में और डिवाइस को Mac से जोड़ने पर Finder में देख सकते हैं।\n**Android:** हाँ। सेटिंग्स में जाएं, फिर मॉडल में, और अलग स्टोरेज स्थान चुनने के लिए “फ़ोल्डर बदलें” विकल्प का उपयोग करें।","faq.ios.a":"जल्द ही App Store पर। iOS के लिए LM Playground को iOS 26 या नया और iPhone 15 Pro या नया, या M1 या नए चिप वाला iPad चाहिए होगा। चैट, विज़न, दस्तावेज़, डिक्टेशन और टूल Android की तरह ही आपके डिवाइस पर चलते हैं।","faq.ios.q":"क्या LM Playground iPhone और iPad पर उपलब्ध है?","faq.q1":"LM Playground क्या है?","faq.q10":"मैं मॉडल कैसे डिलीट करूं?","faq.q11":"सिस्टम प्रॉम्प्ट क्या हैं?","faq.q12":"टूल क्या हैं और कौन से उपलब्ध हैं?","faq.q13":"क्या वेब टूल मेरा डेटा ऑनलाइन भेजते हैं?","faq.q14":"क्या प्रतिक्रिया तैयार होने पर ऐप मुझे सूचित करेगा?","faq.q15":"क्या वॉइस डिक्टेशन मेरी आवाज़ कहीं भेजता है?","faq.q2":"कौन से मॉडल समर्थित हैं?","faq.q3":"मुझे कितनी स्टोरेज जगह चाहिए?","faq.q4":"क्या ऐप को इंटरनेट कनेक्शन चाहिए?","faq.q5":"क्या मेरा डेटा निजी है?","faq.q6":"मॉडल लोड होने में धीमा क्यों है?","faq.q7":"कौन से डिवाइस सबसे अच्छे काम करते हैं?","faq.q8":"क्या मैं कस्टम GGUF मॉडल लोड कर सकता हूं?","faq.q9":"क्या मैं मॉडल का स्टोरेज स्थान बदल सकता हूं?","faq.sub":"अब भी अटके हैं? GitHub पर issue खोलें या सीधे संपर्क करें।","faq.title":"वे सवाल जो आपके मन में थे<br/>पूछने से पहले।","features.lead":"चैट, विज़न, दस्तावेज़, आवाज़ और टूल — <b>सब कुछ आपकी जेब में मौजूद चिप पर चलता है।</b>","features.title":"वह सब, जिसकी आप उम्मीद करते हैं।<br/>बाहर कुछ नहीं जाता।","flow.a1":"240 का 15% <b>36</b> है।","flow.a3":"गुरुवार की मीटिंग अब शुक्रवार सुबह 10 बजे होगी।","flow.a4":"नहीं — 391 = <b>17 × 23</b>।","flow.q1":"240 का 15% कितना है?","flow.q2":"“कल मिलते हैं” का जापानी में अनुवाद करो।","flow.q3":"इस ईमेल का सार एक लाइन में बताओ।","flow.q4":"क्या 391 एक अभाज्य संख्या है?","footer.about":"iPhone और iPad (जल्द आ रहा है) और Android पर बड़े भाषा मॉडल लोकली चलाने वाला ओपन-सोर्स ऐप। <a href=\"https://github.com/ggml-org/llama.cpp\">llama.cpp</a> पर आधारित। MIT लाइसेंस।","footer.build":"बिल्ड","footer.build.issues":"इश्यू ट्रैकर","footer.build.releases":"रिलीज़","footer.contact":"संपर्क","footer.email":"ईमेल","footer.privacy":"गोपनीयता नीति","footer.product":"उत्पाद","footer.product.models":"सभी मॉडल","hero.cta.android":"Google Play पर पाएँ","hero.cta.ios":"App Store · जल्द","hero.lead":"बड़े भाषा मॉडल <b>पूरी तरह ऑफ़लाइन</b> चलाएँ। न क्लाउड, न अकाउंट, न ट्रैकिंग — मुफ़्त और ओपन सोर्स।","hero.note":"iPhone 15 Pro+ और M1+ iPad · Android 11+ · MIT लाइसेंस","hero.publishers":"इनके ओपन-वेट मॉडल चलाता है","hero.title":"निजी AI।<br/>सीधे आपके फ़ोन पर।","how.dl.choose":"मॉडल चुनें","how.dl.downloading":"डाउनलोड हो रहा है · Wi‑Fi","how.dl.eta":"{speed} MB/s · {time} बाकी","how.dl.ready":"✓ चैट के लिए तैयार","how.dl.saved":"डिवाइस पर सेव है","how.dl.wait":"इंतज़ार…","how.dl.waiting":"टैप का इंतज़ार","how.eyebrow":"कैसे काम करता है","how.lead":"आज़माने के लिए किसी मॉडल पर टैप करें — <b>या बस देखते रहें।</b>","how.s1.body":"40 ओपन मॉडल में से चुनें, या अपना GGUF लाएँ।","how.s1.title":"मॉडल चुनें","how.s2.body":"बैकग्राउंड में डाउनलोड, प्रोग्रेस के साथ, और रुकने पर अपने-आप फिर से शुरू।","how.s2.title":"एक बार डाउनलोड करें","how.s3.body":"सोचने की प्रक्रिया चैट में ही दिखती है। हिस्ट्री आपके डिवाइस पर रहती है।","how.s3.title":"ऑफ़लाइन चैट करें","how.title":"तीन टैप में<br/>पहला टोकन।","lang.body":"पूरा ऐप 28 भाषाओं में अनुवादित है, और पहली बार खोलने पर यह आपकी भाषा बोलने वाला मॉडल सुझाता है। <a class=\"link\" href=\"https://github.com/andriydruk/LMPlayground\">अनुवाद बेहतर बनाएँ</a>","lang.eyebrow":"भाषाएँ","lang.title":"आपकी भाषा बोलता है।","meta.title":"LM Playground — आपके फ़ोन पर निजी AI","models.browse":"सभी मॉडल ब्राउज़ करें","models.byo":"कुछ खास चाहिए? <b>अपना GGUF लाएँ</b> — ऐप फ़ाइल से ही चैट टेम्पलेट पढ़ लेता है।","models.eyebrow":"मॉडल","models.lead":"मॉडल वह AI है जो चैट के पीछे काम करता है — <b>एक फ़ाइल, जिसे आप बस एक बार डाउनलोड करते हैं।</b> बड़े मॉडल ज़्यादा जानते हैं और बेहतर तर्क करते हैं, लेकिन उन्हें ज़्यादा मेमोरी चाहिए। अपने फ़ोन की RAM चुनें और देखें कि कौन-से मॉडल सही रहेंगे।","models.ram.note":"सुझाए गए मॉडल वे हैं जो फ़िट होते हैं और सबसे ज़्यादा डाउनलोड किए गए हैं। iPhone 15 Pro और नए मॉडल में 8 GB है; Android पर सेटिंग्स → फ़ोन के बारे में देखें।","models.ram.q":"आपके फ़ोन में कितनी RAM है?","models.title":"अपने फ़ोन के लिए<br/>सही दिमाग़ चुनें।","mp.byo.android":".gguf फ़ाइल को सेटिंग्स → मॉडल में चुने गए फ़ोल्डर में रखें। यह बिल्ट-इन मॉडलों के साथ दिखने लगेगी।","mp.byo.body":"चैट टेम्पलेट और टोकनाइज़र सीधे फ़ाइल से पढ़े जाते हैं, इसलिए ज़्यादातर GGUF मॉडल बस चल जाते हैं। अगर कोई न चले, तो <a class=\"link\" href=\"https://github.com/andriydruk/LMPlayground/issues\">GitHub पर हमें बताएँ</a>","mp.byo.chat":"किसी भी दूसरे मॉडल की तरह इसे मॉडल चयनकर्ता से चुनें।","mp.byo.chat.title":"चैट शुरू करें","mp.byo.eyebrow":"अपना मॉडल लाएँ","mp.byo.ios":"सेटिंग्स → मॉडल में इंपोर्ट करें पर टैप करें, या Files ऐप में फ़ाइल को ऐप के Models फ़ोल्डर में कॉपी करें।","mp.byo.ios.title":"iPhone और iPad","mp.byo.title":"आपका पसंदीदा नहीं दिखा?<br/>कोई भी GGUF लोड करें।","mp.count.models":"मॉडल","mp.count.publishers":"पब्लिशर","mp.count.tools":"टूल इस्तेमाल करते हैं","mp.count.vision":"इमेज देखते हैं","mp.downloads":"{n} डाउनलोड / महीना","mp.empty":"कोई मॉडल मेल नहीं खाता। दूसरा फ़िल्टर आज़माएँ — या अपना GGUF लाएँ।","mp.f.all":"सभी","mp.f.new":"नए","mp.f.small":"1 GB से कम","mp.lead":"फ़ोन के लिए चुने और ट्यून किए गए ओपन मॉडल। <b>हर मॉडल पूरी तरह आपके डिवाइस पर चलता है</b> — एक बार डाउनलोड करें, फिर हमेशा ऑफ़लाइन काम करता है।","mp.meta.title":"मॉडल — LM Playground","mp.search":"मॉडल खोजें","mp.shown.all":"सभी {n} मॉडल दिखाए जा रहे हैं","mp.shown.some":"{total} में से {n} मॉडल दिखाए जा रहे हैं","mp.sort":"मॉडल क्रमबद्ध करें","mp.sort.large":"सबसे बड़े पहले","mp.sort.name":"नाम","mp.sort.new":"सबसे नए पहले","mp.sort.popular":"सबसे लोकप्रिय","mp.sort.small":"सबसे छोटे पहले","mp.source":"डाउनलोड का मतलब है पिछले 30 दिनों में Hugging Face से हर मॉडल की GGUF फ़ाइलों के डाउनलोड (21 नवंबर 2026 को जाँचा गया)।","mp.title":"हर मॉडल।<br/>बस एक टैप दूर।","nav.download":"डाउनलोड","nav.faq":"सामान्य प्रश्न","nav.features":"सुविधाएँ","nav.how":"कैसे काम करता है","nav.models":"मॉडल","nav.privacy":"गोपनीयता","phone.a":"मशीन लर्निंग कृत्रिम बुद्धिमत्ता की एक शाखा है जहाँ कंप्यूटर स्पष्ट रूप से प्रोग्राम किए जाने के बजाय **डेटा से सीखते** हैं।\n\nमुख्य अवधारणाएँ:\n\n• **प्रशिक्षण**: एल्गोरिदम को डेटा देना\n• **मॉडल**: डेटा से सीखे गए पैटर्न\n• **अनुमान**: नए डेटा पर भविष्यवाणी करना","phone.a1":"4% वार्षिक चक्रवृद्धि ब्याज पर, $5,000 बढ़कर 10 साल में **$7,401.22** हो जाते हैं — यानी 5,000 × 1.04^10। तो आप अपनी $5,000 मूल राशि के ऊपर लगभग **$2,401** का ब्याज कमाएँगे।","phone.a2":"समीक्षक काफी हद तक सकारात्मक हैं। खूबियाँ: कहीं ज़्यादा चमकदार **3000-nit डिस्प्ले**, करीब **20%** बेहतर बैटरी लाइफ़, और एक ज़्यादा शार्प टेलीफ़ोटो कैमरा, साथ ही तेज़ ऑन-डिवाइस AI। मुख्य शिकायत है **ऊँची शुरुआती कीमत** — पर ज़्यादातर लोग अब भी इसे अब तक का सबसे बेहतरीन Pixel मानते हैं।","phone.a3":"Karpathy एक **LLM द्वारा बनाए रखे गए विकी** का प्रस्ताव रखते हैं — एक स्थायी, आपस में जुड़ी markdown परत जिसे मॉडल आपके और आपके मूल स्रोतों के बीच बनाता है। हर सवाल पर सब कुछ दोबारा पढ़ने के बजाय, नई सामग्री आने पर यह पेज और लिंक अपडेट करता रहता है, जिससे आपका ज्ञान-आधार हर बार नए सिरे से तैयार होने के बजाय **संचित** होता जाता है।","phone.aD":"शुरुआती छह महीने की अवधि के बाद आप **60 दिन के लिखित नोटिस** के साथ अनुबंध समाप्त कर सकते हैं। आपकी जमा राशि घर खाली करने के **14 दिनों के भीतर** लौटा दी जाती है (धारा 8.2)।","phone.aV":"घनी, घुंघराली क्रीम-सफ़ेद ऊन वाली एक **भेड़**, हरी-भरी पहाड़ी ढलान पर सिर झुकाए चर रही है। बादल भरा आसमान और चट्टानी चरागाह एक ठंडे, ऊंचाई वाले इलाके का संकेत देते हैं।","phone.input":"संदेश","phone.q":"मशीन लर्निंग क्या है?","phone.q1":"अगर मैं $5,000 को 4% वार्षिक ब्याज पर निवेश करूँ, तो 10 साल में इसकी कीमत क्या होगी?","phone.q2":"नए Pixel के बारे में समीक्षक क्या कह रहे हैं?","phone.q3":"इस लेख का सारांश दें: https://gist.github.com/karpathy/442a6bf555914893e9891c11519de94f","phone.qD":"मैं अपना किराया अनुबंध कब समाप्त कर सकता हूँ?","phone.qV":"इस फ़ोटो में कौन-सा जानवर है?","phone.r0":"उपयोगकर्ता एक सरल परिभाषा चाहता है। डेटा से सीखने बनाम स्पष्ट नियमों के अंतर को समझाएँ, फिर मुख्य चरण बताएँ: ट्रेनिंग, मॉडल और इन्फ़रेंस। इसे शुरुआती लोगों के लिए आसान रखें।","phone.r1":"चक्रवृद्धि ब्याज के साथ भविष्य मूल्य: FV = P(1 + r)^n, जहाँ P = 5000, r = 0.04, n = 10। 1.04^10 लगभग 1.4802 है, इसलिए FV लगभग 7401.22 है। ब्याज = FV − P, लगभग 2401।","phone.r2":"नतीजे डिस्प्ले, बैटरी और कैमरे में सुधार पर सहमत हैं, साथ ही तेज़ ऑन-डिवाइस AI पर भी। बार-बार दोहराई गई कमी है ऊँची कीमत। इसे तारीफ़ बनाम मुख्य कमी के रूप में संक्षेप में बताएँ।","phone.r3":"Karpathy एक LLM द्वारा बनाए रखे गए निजी विकी का प्रस्ताव रखते हैं। तीन परतें: अपरिवर्तनीय मूल स्रोत, LLM द्वारा बनाया गया विकी, और एक स्कीमा फ़ाइल। नए स्रोत आने पर मॉडल पेज और क्रॉस-लिंक अपडेट करता है, जिससे ज्ञान संचित होता जाता है। विचार और परतों की संरचना का सारांश दें।","phone.rD":"अंशों के अनुसार शुरुआती छह महीने की अवधि के बाद 60 दिन के लिखित नोटिस से लीज़ खत्म की जा सकती है, और धारा 8.2 जमा राशि के बारे में है: घर खाली करने के 14 दिनों के भीतर वापसी। जवाब में दोनों बातें बतानी हैं।","phone.rV":"उपयोगकर्ता चाहता है कि मैं फ़ोटो में मौजूद जानवर को पहचानूं। यह एक ऊनी भेड़ है जो हरी पहाड़ी ढलान पर सिर झुकाए चर रही है। संक्षेप में उत्तर दूं और इसकी मुख्य विशेषताएं बताऊं।","phone.send":"भेजें","phone.tD":"दस्तावेज़ खोजा जा रहा है","phone.thinking":"सोच रहा हूँ","priv.airplane":"हवाई जहाज़ मोड","priv.body1":"<b>SIM निकालें। Wi‑Fi बंद करें। चैट जारी रखें।</b> मॉडल डाउनलोड होने के बाद, इन्फ़रेंस पूरी तरह आपके फ़ोन पर ही होता है — फ़्लाइट में, मेट्रो में, कहीं भी।","priv.body2":"न अकाउंट, न API कुंजी, न टेलीमेट्री, न एनालिटिक्स। वेब टूल वैकल्पिक हैं और डिफ़ॉल्ट रूप से बंद रहते हैं।","priv.eyebrow":"गोपनीयता","priv.legend.net":"नेटवर्क ट्रैफ़िक","priv.legend.tokens":"आपके फ़ोन पर टोकन","priv.link":"गोपनीयता नीति पढ़ें","priv.sent":"नेटवर्क पर भेजा गया","priv.title":"बनावट से ही निजी।","priv.tokens":"टोकन बनाए गए","priv.wifi":"Wi‑Fi बंद","privacy.date":"प्रभावी तिथि: 2 जून 2026","privacy.intro":"LM Playground में आपका स्वागत है! मैं अपने ऐप का उपयोग करने वाले हर व्यक्ति का विश्वास और भरोसा बनाए रखने के लिए प्रतिबद्ध हूं। यह गोपनीयता नीति बताती है कि ऐप क्या एकत्र करता है और क्या नहीं, आपकी बातचीत कैसे आपके डिवाइस पर ही रहती है, और वे कुछ सीमित स्थितियाँ — जैसे वैकल्पिक वेब टूल — जिनमें जानकारी आपके डिवाइस से बाहर जाती है, ताकि आपको हमेशा पता रहे कि क्या अपेक्षित है।","privacy.s1.body":"मैं, Andriy Druk, LM Playground का डेवलपर, अपने ऐप के उपयोगकर्ताओं से कोई भी व्यक्तिगत जानकारी एकत्र, संग्रहीत, उपयोग या साझा नहीं करता। कोई खाता नहीं, कोई विज्ञापन नहीं, और कोई उपयोग एनालिटिक्स या ट्रैकिंग नहीं है। ऐप आपकी गोपनीयता को प्राथमिकता देकर डिज़ाइन किया गया है, ताकि आप इसे अपने व्यक्तिगत डेटा से समझौता किए बिना उपयोग कर सकें।","privacy.s1.title":"1. कोई व्यक्तिगत जानकारी संग्रह नहीं","privacy.s2.body":"आपकी बातचीत, सिस्टम प्रॉम्प्ट और मॉडल के जवाब आपके डिवाइस पर ही ऑन-डिवाइस मॉडल द्वारा स्थानीय रूप से प्रोसेस होते हैं। यह सामग्री इनफ़रेंस के लिए कभी मुझे या किसी सर्वर को नहीं भेजी जाती। जब तक आप इंटरनेट तक पहुँचने वाली किसी सुविधा का उपयोग नहीं करते, यह आपके डिवाइस पर ही रहती है, जैसा कि नीचे बताया गया है।","privacy.s2.title":"2. डिवाइस पर प्रोसेसिंग","privacy.s3.body":"LM Playground सिर्फ़ दो कामों के लिए इंटरनेट से जुड़ता है: आपके चुने हुए मॉडल फ़ाइल डाउनलोड करने के लिए, और — सिर्फ़ तब जब आप उन्हें चालू करें — वैकल्पिक वेब टूल चलाने के लिए। ऐप में कोई विज्ञापन, टेलीमेट्री या उपयोग विश्लेषण नहीं है, और यह आपकी गतिविधि की जानकारी मुझे नहीं भेजता।","privacy.s3.title":"3. इंटरनेट एक्सेस","privacy.s4.body":"सक्षम मॉडल वैकल्पिक टूल का उपयोग कर सकते हैं, जो डिफ़ॉल्ट रूप से बंद रहते हैं। जब आप वेब टूल चालू करते हैं, तो कुछ जानकारी आपके डिवाइस से बाहर जाती है: वेब खोज टूल मॉडल की खोज क्वेरी DuckDuckGo को भेजता है, और वेब पेज फ़ेच करें टूल उन वेबसाइटों से वे पेज डाउनलोड करता है जिन्हें मॉडल खोलने का निर्णय लेता है। वे अनुरोध तीसरे पक्ष की साइटों द्वारा उनकी अपनी गोपनीयता नीतियों के तहत संभाले जाते हैं — मुझे न तो वे मिलते हैं और न मैं उन्हें संग्रहीत करता हूं। JavaScript चलाएँ टूल पूरी तरह आपके डिवाइस पर एक सैंडबॉक्स में चलता है जिसमें इंटरनेट एक्सेस नहीं होता। सब कुछ ऑफ़लाइन रखने के लिए, बस टूल बंद रहने दें।","privacy.s4.title":"4. टूल और वेब एक्सेस","privacy.s5.body":"LM Playground के डेवलपर के रूप में, मैं किसी भी समय इस गोपनीयता नीति को अपडेट करने का अधिकार सुरक्षित रखता हूं। कोई भी परिवर्तन अपडेट की गई नीति पोस्ट करने के तुरंत बाद प्रभावी होगा। उपयोगकर्ताओं को इस पृष्ठ को समय-समय पर देखने और यह जानने के लिए प्रोत्साहित किया जाता है कि उनकी गोपनीयता कैसे सुरक्षित है।","privacy.s5.title":"5. गोपनीयता नीति अपडेट","privacy.s6.body":"LM Playground का उपयोग करके, आप इस गोपनीयता नीति को स्वीकार और सहमत करते हैं। यदि आप नीति से सहमत नहीं हैं, तो कृपया ऐप का उपयोग न करें। इस नीति में किसी भी अपडेट या परिवर्तन के प्रकाशन के बाद ऐप का आपका निरंतर उपयोग उन परिवर्तनों की आपकी स्वीकृति माना जाएगा।","privacy.s6.title":"6. इस नीति की स्वीकृति","privacy.s7.body":"यदि आपके मेरी गोपनीयता नीति के बारे में कोई प्रश्न या सुझाव हैं, तो मुझसे संपर्क करने में संकोच न करें।","privacy.s7.title":"7. मुझसे संपर्क करें","privacy.title":"गोपनीयता नीति","prompts.new":"नया सिस्टम प्रॉम्प्ट","qa.stuck":"अब भी अटके हैं? <a class=\"link\" href=\"https://github.com/andriydruk/LMPlayground/issues\">GitHub पर इश्यू खोलें</a>","qa.title":"सवाल?<br/>जवाब।","store.android.small":"इसे पाएँ","store.ios.small":"जल्द आ रहा है","tools.t1.title":"JavaScript चलाएँ","tools.t2.title":"वेब खोज","tools.t3.title":"वेब पेज फ़ेच करें","tp.balanced":"संतुलित","tp.context":"संदर्भ 4,096","tp.creative":"रचनात्मक","tp.focused":"केंद्रित","tp.o1":"समुद्री नीला।","tp.o2":"बंदरगाह की धुंध — हल्का, ठंडा स्लेटी-नीला।","tp.o3":"आधी रात का बाग़: गहरा जामुनी, हरे की हल्की झलक के साथ।","tp.o4":"आँधी-तूफ़ानी लैवेंडर, ताँबे की चित्तियों वाला — जैसे टीन की छत पर बारिश।","tp.o5":"मखमली खरखराहट — वह रंग, जो रात 3 बजे रेडियो गुनगुनाता है, जब कोई नहीं सुन रहा होता।","tp.precise":"सटीक","tp.q":"किसी नए पेंट रंग का नाम सुझाओ।","tp.repeat":"दोहराव पेनल्टी 1.1","tp.seed":"सीड","tp.surprising":"चौंकाने वाला","tp.temperature":"तापमान","tp.wild":"बेलगाम","ui.next":"अगला","ui.prev":"पिछला","ui.theme":"लाइट या डार्क थीम बदलें","units.tokens":"%d टोकन","why.devices.body":"iPhone 15 Pro और नए मॉडल, और M1 iPad के लिए जल्द आ रहा है। Android 11 और नए वर्शन पर आज ही चलता है।","why.devices.ipad":"iPad · जल्द","why.devices.iphone":"iPhone · जल्द","why.devices.title":"iPhone, iPad और Android।","why.engine.body":"लोकल AI के पीछे का ओपन-सोर्स इंजन। कोई भी GGUF फ़ाइल लाएँ, बस चल जाएगी।","why.engine.title":"llama.cpp की ताकत से।","why.free.body":"न सब्सक्रिप्शन, न अकाउंट, न विज्ञापन। कोड की हर लाइन GitHub पर है।","why.free.title":"मुफ़्त। हमेशा के लिए।","why.size.body":"चालीस ओपन मॉडल — हर फ़ोन में समा जाने वाले छोटे मॉडलों से लेकर फ़्लैगशिप फ़ोन के लिए तर्क करने वाले दिग्गजों तक। नीचे का हर बिंदु एक मॉडल है, जिसे आप डाउनलोड कर सकते हैं।","why.size.title":"267 MB से 12 GB तक।","why.speed.body":"iPhone और iPad पर Metal, और Android पर Vulkan के साथ GPU एक्सेलरेशन।","why.speed.title":"जैसे-जैसे सोचता है, जवाब आता जाता है।","why.title":"जेब में समा जाए, इतना छोटा।<br/>काम आए, इतना समझदार।"};
